from jsonb_to_recordset($json$[{"id":"che-pe-201","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the first two halogens, the more negative electron gain enthalpy belongs to","options":["fluorine","chlorine","neon","sodium"],"answer_index":1,"explanation":"Cl is more exothermic than F, a well-known exception to the simple down-group trend.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-202","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The second electron gain enthalpy of an atom is always","options":["more negative than the first","positive","zero","equal to the first"],"answer_index":1,"explanation":"A negative ion must accept another electron, so energy is required and ΔegH₂ > 0.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-203","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Conversion of O⁻(g) to O²⁻(g) is endothermic because a negative ion must","options":["lose two protons","accept another electron against its own charge","enter the 1s shell","become a cation"],"answer_index":1,"explanation":"Electron–electron repulsion in O⁻ makes the second attachment unfavourable; oxides form in the lattice, not as free O²⁻(g).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-204","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electron affinity is often quoted as the negative of the","options":["ionisation enthalpy","electron gain enthalpy","electronegativity","atomic radius"],"answer_index":1,"explanation":"Many older tables list EA as a positive number equal to −ΔegH when attachment is exothermic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-205","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine has a less negative electron gain enthalpy than chlorine because the compact 2p cloud of F suffers","options":["almost no inter-electronic repulsion","strong electron–electron repulsion when an extra electron is added","a vacant 3d subshell","lanthanoid contraction"],"answer_index":1,"explanation":"The incoming electron is forced into a very small 2p orbital already crowded with electrons.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-206","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among F, Cl, Br and I, the most negative electron gain enthalpy belongs to","options":["fluorine","chlorine","bromine","iodine"],"answer_index":1,"explanation":"Chlorine combines a high Zeff with a large enough 3p orbital to avoid the extreme repulsion seen in F.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-207","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Nitrogen has a near-zero or slightly positive electron gain enthalpy because its 2p subshell is already","options":["empty","half filled","completely filled","a d subshell"],"answer_index":1,"explanation":"Adding an electron to 2p³ forces pairing and destroys the half-filled stability, so attachment is unfavourable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-208","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium and magnesium have unfavourable (near-zero or positive) electron gain enthalpies because they possess","options":["half-filled 2p sets","filled ns² subshells","incomplete 1s shells","seven valence electrons"],"answer_index":1,"explanation":"The extra electron would have to enter a higher np orbital against a closed s pair.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-209","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among carbon, nitrogen, oxygen and fluorine, the most negative electron gain enthalpy is that of","options":["carbon","nitrogen","oxygen","fluorine"],"answer_index":3,"explanation":"Fluorine is one electron short of neon and, despite the F/Cl anomaly, is still the most exothermic of this period-2 set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-210","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Chlorine outruns fluorine in electron gain enthalpy because the incoming electron enters a larger 3p orbital with less repulsion, even though fluorine has the","options":["lower electronegativity","higher electronegativity and higher Zeff","greater number of shells","smaller nuclear charge"],"answer_index":1,"explanation":"Two trends compete: F is smaller and more electronegative, yet inter-electronic repulsion in the compact 2p cloud makes ΔegH(F) less negative than ΔegH(Cl).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
